// files-query-lint scans Python source for two invariants around files-svc's
// corpus-scoped tables:
//
//  1. (deleted_at rule) SELECTs against files.documents must carry the trash
//     filter "deleted_at IS NULL".
//
//     Allowed exceptions:
//     - Query constant name contains "TRASH" / "SWEEPER" / "PURGE" / "CLEANUP"
//     (intentionally trash-aware or state-agnostic).
//     - Query body contains "DELETED_AT IS NOT NULL" (explicit trash filter).
//     - Constant is preceded by a comment line containing the inline marker
//     "files-query-lint: allow-trash-state-agnostic" (durable opt-out for
//     state-agnostic reads whose name doesn't match the token convention).
//     - Statement is not a SELECT (writes don't need the filter).
//
//  2. (corpus-visibility rule) any query naming files.documents,
//     files.folders, or files.ingest_jobs must carry the shared
//     _CORPUS_VISIBLE_PREDICATE EXISTS gate, OR a reasoned exemption:
//     - Plain INSERTs are exempt structurally — a subquery on an INSERT
//     values list gates nothing (callers must pre-check corpus visibility
//     at the handler layer instead; this linter cannot verify that).
//     - A named query constant may be exempt if its name is in the
//     hardcoded corpusVisibilityExemptions allowlist below AND it carries
//     a reasoned marker (a comment within lookback distance containing
//     "ungated" or "Inline-SQL audit (Service-Layer-Security)" plus
//     actual explanatory text — a bare marker with no reason fails).
//     - An allowlist entry naming a query that no longer exists anywhere
//     in the scanned tree is itself a lint failure (stale exemption).
//     - Inline SQL string literals (outside db/queries.py's named
//     constants — see handlers/, sweepers/, inbox_provisioner/) are
//     checked the same way, using the marker only (no allowlist, since
//     they have no stable name to track).
package main

import (
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

// Matches Python constants of the shape:  NAME = """ ... """ or
// NAME = f""" ... """ (f-strings are used for parameterized query
// templates). DOTALL via the (?s) flag handles multi-line bodies.
var queryConstRE = regexp.MustCompile(`(?s)([A-Z_][A-Z0-9_]*)\s*=\s*f?"""(.+?)"""`)

// Exceptions: query names containing any of these tokens are exempt.
// Order matches the spec's design — TRASH for the trash list/sweeper,
// PURGE for state-agnostic purge locks, CLEANUP for state-agnostic
// cleanup locks, SWEEPER for the sweeper candidate scan.
var allowedNameTokens = []string{"TRASH", "SWEEPER", "PURGE", "CLEANUP"}

// Inline allow marker. Must appear in a Python comment within the
// preceding allowMarkerLookback lines of the constant definition.
const allowMarker = "files-query-lint: allow-trash-state-agnostic"
const allowMarkerLookback = 10

// hasAllowMarker reports whether the comment block immediately preceding
// matchStart in content contains the allow marker. The preceding block
// is bounded by a blank line or non-comment code; we also cap the scan
// at allowMarkerLookback lines for safety.
func hasAllowMarker(content string, matchStart int) bool {
	prefix := content[:matchStart]
	lines := strings.Split(prefix, "\n")
	// Drop the trailing partial line (the one the constant lives on).
	if len(lines) > 0 {
		lines = lines[:len(lines)-1]
	}
	// Walk backward through contiguous comment / blank lines.
	scanned := 0
	for i := len(lines) - 1; i >= 0 && scanned < allowMarkerLookback; i-- {
		scanned++
		line := strings.TrimSpace(lines[i])
		if line == "" {
			// Blank line ends the comment block.
			return false
		}
		if !strings.HasPrefix(line, "#") {
			// Hit non-comment code — no marker for this constant.
			return false
		}
		if strings.Contains(line, allowMarker) {
			return true
		}
	}
	return false
}

func lint(content string) []string {
	var errs []string
	matches := queryConstRE.FindAllStringSubmatchIndex(content, -1)
	for _, idx := range matches {
		// idx layout: [start, end, nameStart, nameEnd, bodyStart, bodyEnd]
		start := idx[0]
		name := content[idx[2]:idx[3]]
		body := content[idx[4]:idx[5]]
		bodyU := strings.ToUpper(body)
		if !strings.Contains(bodyU, "FROM FILES.DOCUMENTS") {
			continue
		}
		// Only flag SELECTs (writes don't need the filter).
		trimmed := strings.TrimSpace(bodyU)
		if !strings.HasPrefix(trimmed, "SELECT") && !strings.HasPrefix(trimmed, "WITH") {
			continue
		}
		// Allow intentional trash-aware / state-agnostic queries by name.
		nameAllowed := false
		for _, token := range allowedNameTokens {
			if strings.Contains(name, token) {
				nameAllowed = true
				break
			}
		}
		if nameAllowed {
			continue
		}
		// Allow queries that explicitly assert the opposite predicate.
		if strings.Contains(bodyU, "DELETED_AT IS NOT NULL") {
			continue
		}
		// Allow queries that opt out via the inline marker in the
		// preceding comment block.
		if hasAllowMarker(content, start) {
			continue
		}
		if !strings.Contains(bodyU, "DELETED_AT IS NULL") {
			errs = append(errs, fmt.Sprintf("%s: SELECT on files.documents missing 'WHERE deleted_at IS NULL'", name))
		}
	}
	return errs
}

// --- corpus-visibility rule ---

// Tables whose RLS is org-scoped ONLY — every query naming one of these must
// carry files.corpora's _CORPUS_VISIBLE_PREDICATE EXISTS gate (directly or
// via a reasoned exemption), or a same-org caller who supplies/guesses
// another user's id can read/mutate rows inside someone else's PRIVATE
// corpus. Matches the #1792-era IDOR class fixed on files.documents/
// files.folders/files.ingest_jobs.
var gatedTables = []string{"FILES.DOCUMENTS", "FILES.FOLDERS", "FILES.INGEST_JOBS"}

// The shared SQL fragment every gated query interpolates. Its literal
// presence in a query body is the pass condition for the corpus-visibility
// rule — precise and unambiguous, unlike a heuristic keyword scan.
const corpusVisiblePredicateToken = "_CORPUS_VISIBLE_PREDICATE"

// Hardcoded, code-review-controlled allowlist of named query constants that
// are deliberately left ungated. A query NOT in this list fails the rule
// regardless of any comment near it — only adding a name here (a diff to
// this file) can silence the rule for a *named* query.
//
// Bidirectional: staleExemptions() below fails the build if any of these
// names no longer exists anywhere in the scanned tree, so deleting a query
// can't leave a dangling exemption forever.
var corpusVisibilityExemptions = []string{
	// Trusted no-user-context paths: the ingest worker and the nightly
	// trash sweeper open their tx with a service account and NO user_id,
	// so _CORPUS_VISIBLE_PREDICATE would strand every PRIVATE/personal-
	// inbox row. RLS org-isolation still applies via the tx's org_id GUC.
	"GET_DOCUMENT_FOR_INGEST",
	"LOCK_INGEST_JOB",
	"UPDATE_INGEST_JOB_STATUS",
	// #256 known-type stamp: same worker tx as GET_DOCUMENT_FOR_INGEST, and
	// its document_id comes from the ingest job's own row rather than from a
	// caller, so there is no id for a same-org user to guess. A visibility
	// gate would additionally leave every personal-inbox upload permanently
	// unclassified, since the worker has no user_id to satisfy it with.
	"STAMP_DOCUMENT_KNOWN_TYPE",
	"SELECT_TRASH_SWEEPER_CANDIDATES",
	"LOCK_DOCUMENT_FOR_SWEEP",
	"LOCK_DOCUMENT_FOR_CLEANUP",
	// Purge/trash-admin exemption: authorization here is the forgeable
	// x-org-role header (finding #1792, unfixed) rather than corpus
	// visibility. Gating these would let a forged header WIDEN private-
	// corpus reads instead of narrowing them. Stays open until #1792 lands.
	"LOCK_DOCUMENT_FOR_PURGE",
	"LIST_TRASH_BY_CORPUS",
	// #2473 right-to-be-forgotten purge candidate scans: a hard purge must
	// see every PRIVATE/TEAM document to purge it, so gating on visibility
	// would strand private rows past their owner's own purge request.
	"LIST_DOCUMENT_IDS_FOR_ORG_PURGE",
	"LIST_DOCUMENT_IDS_FOR_USER_PURGE",
	// Operate only on ids already resolved through an upstream gated read or
	// lock in the same transaction, so re-gating them would be redundant.
	// DELETE_DOCUMENT additionally runs on the no-user sweeper path, where a
	// gate would silently stop the 30-day auto-purge. Each carries an
	// INTENTIONALLY UNGATED marker in queries.py explaining which upstream
	// query establishes visibility.
	"DELETE_DOCUMENT",
	"RESOLVE_FOLDER_PATH",
	"TRASH_DOCUMENT_FROM_CASCADE",
	// One-shot data-migration RPCs replaying trusted legacy rows verbatim
	// (keyed on legacy_id, not on a caller-guessed id) — no corpus-guessing
	// attack surface.
	"INSERT_ENTITY_TYPE_WITH_LEGACY",
	"INSERT_RELATIONSHIP_TYPE_WITH_LEGACY",
	"INSERT_CORPUS_WITH_LEGACY",
	"INSERT_ENTITY_WITH_LEGACY",
	"INSERT_EDGE_WITH_LEGACY",
	"INSERT_DOCUMENT_WITH_LEGACY",
	"INSERT_CHUNK_WITH_LEGACY",
}


// Marker tokens (case-insensitive) that flag a nearby comment as a reasoned
// corpus-visibility exemption. Both forms are already in use on disk:
// "ungated" / "INTENTIONALLY UNGATED" on named query constants in
// queries.py, and "Inline-SQL audit (Service-Layer-Security)" on inline SQL
// call sites in handlers/sweepers.
var corpusVisibilityMarkerTokens = []string{"ungated", "inline-sql audit (service-layer-security)"}

// How far back (in lines) to look for a marker. Named constants usually have
// their comment directly above (0-6 line gap in practice); inline call sites
// separate the marker comment from the SQL string literal by the
// surrounding Python call syntax (up to ~14 lines observed in
// handlers/folder.py and handlers/document/_trash.py).
const exemptionMarkerLookbackLines = 18

// Minimum length of comment text left over after stripping the marker
// token(s) — distinguishes a bare "# INTENTIONALLY UNGATED" (no reason,
// must fail) from a real explanation.
const exemptionReasonMinLen = 15

// Anonymous (non-constant) string literals: triple-quoted (optionally
// f-prefixed) or single-line double-quoted. Used to catch inline SQL passed
// directly as a call argument, e.g. `conn.execute("SELECT ... FROM
// files.documents ...")`, which the named-constant regex above never sees.
var inlineStringRE = regexp.MustCompile(`(?s)f?("""(?:.*?)"""|"(?:[^"\n\\]|\\.)*")`)

func namesGatedTable(bodyU string) bool {
	for _, t := range gatedTables {
		if strings.Contains(bodyU, t) {
			return true
		}
	}
	return false
}

func isInsertOnly(bodyU string) bool {
	return strings.HasPrefix(strings.TrimSpace(bodyU), "INSERT")
}

// isLikelySQLStatement guards the corpus-visibility rule against anonymous
// (non-constant) string literals that merely mention a gated table name in
// prose — module/function docstrings routinely say things like "the
// files.ingest_jobs row" without containing any SQL at all. Only strings
// that actually open with a SQL statement keyword are considered.
func isLikelySQLStatement(bodyU string) bool {
	trimmed := strings.TrimSpace(bodyU)
	for _, kw := range []string{"SELECT", "WITH", "UPDATE", "DELETE", "INSERT"} {
		if strings.HasPrefix(trimmed, kw) {
			return true
		}
	}
	return false
}

func hasCorpusVisiblePredicate(bodyU string) bool {
	return strings.Contains(bodyU, corpusVisiblePredicateToken)
}

func isCorpusVisibilityExempt(name string) bool {
	for _, n := range corpusVisibilityExemptions {
		if n == name {
			return true
		}
	}
	return false
}


// allCorpusVisibilityExemptions is every name tracked for the bidirectional
// stale-exemption check. There is exactly one exemption mechanism: allowlist
// membership PLUS a reasoned in-file marker. No name is exempt on allowlist
// membership alone.
func allCorpusVisibilityExemptions() []string {
	all := make([]string, 0, len(corpusVisibilityExemptions))
	all = append(all, corpusVisibilityExemptions...)
	return all
}

// hasExemptionMarker looks within exemptionMarkerLookbackLines lines before
// matchStart for one of corpusVisibilityMarkerTokens, and requires
// meaningful text beyond the marker itself.
func hasExemptionMarker(content string, matchStart int) bool {
	prefix := content[:matchStart]
	lines := strings.Split(prefix, "\n")
	if len(lines) > 0 {
		lines = lines[:len(lines)-1] // drop the trailing partial line
	}
	start := 0
	if len(lines) > exemptionMarkerLookbackLines {
		start = len(lines) - exemptionMarkerLookbackLines
	}
	window := strings.ToLower(strings.Join(lines[start:], "\n"))

	found := false
	reason := window
	for _, tok := range corpusVisibilityMarkerTokens {
		if strings.Contains(window, tok) {
			found = true
			reason = strings.ReplaceAll(reason, tok, "")
		}
	}
	if !found {
		return false
	}
	reason = strings.ReplaceAll(reason, "intentionally", "")
	reason = strings.ReplaceAll(reason, "#", "")
	reason = strings.TrimSpace(reason)
	return len(reason) >= exemptionReasonMinLen
}

func lineNumber(content string, pos int) int {
	return strings.Count(content[:pos], "\n") + 1
}

// checkCorpusVisibility evaluates a single query (named or inline) against
// the corpus-visibility rule. requireAllowlist gates named constants through
// corpusVisibilityExemptions; inline literals (no stable name) are gated on
// the marker alone.
func checkCorpusVisibility(content string, matchStart int, name, body string, requireAllowlist bool) string {
	bodyU := strings.ToUpper(body)
	if !isLikelySQLStatement(bodyU) {
		return ""
	}
	if !namesGatedTable(bodyU) {
		return ""
	}
	if isInsertOnly(bodyU) {
		return ""
	}
	if hasCorpusVisiblePredicate(bodyU) {
		return ""
	}
	if requireAllowlist {
		if !isCorpusVisibilityExempt(name) {
			return fmt.Sprintf("%s: query on a corpus-scoped table (files.documents/files.folders/files.ingest_jobs) missing the _CORPUS_VISIBLE_PREDICATE gate and not in the corpus-visibility exemption allowlist", name)
		}
	}
	if !hasExemptionMarker(content, matchStart) {
		return fmt.Sprintf("%s: query on a corpus-scoped table missing the _CORPUS_VISIBLE_PREDICATE gate, and no reasoned exemption marker (marker with no reason text does not count) found nearby", name)
	}
	return ""
}

// stripStringQuotes removes the enclosing Python string delimiters
// (triple-double-quote or single double-quote) from a raw regex match so
// the SQL-keyword and table-name checks see the actual query text, not the
// quote characters.
func stripStringQuotes(raw string) string {
	if strings.HasPrefix(raw, `"""`) && strings.HasSuffix(raw, `"""`) && len(raw) >= 6 {
		return raw[3 : len(raw)-3]
	}
	if strings.HasPrefix(raw, `"`) && strings.HasSuffix(raw, `"`) && len(raw) >= 2 {
		return raw[1 : len(raw)-1]
	}
	return raw
}

func withinAnySpan(start, end int, spans [][2]int) bool {
	for _, s := range spans {
		if start >= s[0] && end <= s[1] {
			return true
		}
	}
	return false
}

// lintCorpusVisibility scans content for both named query constants and
// anonymous inline SQL string literals, applying the corpus-visibility rule
// to each.
func lintCorpusVisibility(content string) []string {
	var errs []string

	namedMatches := queryConstRE.FindAllStringSubmatchIndex(content, -1)
	namedSpans := make([][2]int, 0, len(namedMatches))
	for _, idx := range namedMatches {
		start, end := idx[0], idx[1]
		namedSpans = append(namedSpans, [2]int{start, end})
		name := content[idx[2]:idx[3]]
		body := content[idx[4]:idx[5]]
		if e := checkCorpusVisibility(content, start, name, body, true); e != "" {
			errs = append(errs, e)
		}
	}

	for _, idx := range inlineStringRE.FindAllStringSubmatchIndex(content, -1) {
		start, end := idx[0], idx[1]
		if withinAnySpan(start, end, namedSpans) {
			continue // already handled as part of a named constant above
		}
		body := stripStringQuotes(content[idx[2]:idx[3]])
		label := fmt.Sprintf("<inline SQL at line %d>", lineNumber(content, start))
		if e := checkCorpusVisibility(content, start, label, body, false); e != "" {
			errs = append(errs, e)
		}
	}

	return errs
}

// collectDefinedNames records every `NAME = f?"""..."""` constant name found
// in content, for the stale-exemption check below.
func collectDefinedNames(content string, into map[string]bool) {
	for _, m := range queryConstRE.FindAllStringSubmatch(content, -1) {
		into[m[1]] = true
	}
}

// staleExemptions is the bidirectional half of the corpus-visibility rule:
// an allowlist entry naming a query that no longer exists anywhere in the
// scanned tree must fail the lint, so deleting a query doesn't leave a
// dangling exemption behind forever.
func staleExemptions(defined map[string]bool) []string {
	var errs []string
	for _, name := range allCorpusVisibilityExemptions() {
		if !defined[name] {
			errs = append(errs, fmt.Sprintf("stale exemption: %q is in files-query-lint's corpus-visibility exemption allowlist but is no longer defined anywhere in the scanned tree", name))
		}
	}
	return errs
}

// defaultRoots is scanned when no paths are given on the command line. It
// covers db/queries.py's named constants AND the inline SQL sites audited
// under handlers/, sweepers/, and inbox_provisioner/ (widened beyond db/ so
// the corpus-visibility rule actually sees them).
var defaultRoots = []string{"services/files-svc/src/files_svc"}

func main() {
	roots := defaultRoots
	if len(os.Args) > 1 {
		roots = os.Args[1:]
	}

	var anyErr bool
	defined := map[string]bool{}

	for _, root := range roots {
		_ = filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
			if err != nil || info.IsDir() || !strings.HasSuffix(path, ".py") {
				return err
			}
			data, err := os.ReadFile(path)
			if err != nil {
				return err
			}
			content := string(data)
			collectDefinedNames(content, defined)
			for _, e := range lint(content) {
				fmt.Fprintf(os.Stderr, "%s: %s\n", path, e)
				anyErr = true
			}
			for _, e := range lintCorpusVisibility(content) {
				fmt.Fprintf(os.Stderr, "%s: %s\n", path, e)
				anyErr = true
			}
			return nil
		})
	}

	for _, e := range staleExemptions(defined) {
		fmt.Fprintln(os.Stderr, e)
		anyErr = true
	}

	if anyErr {
		fmt.Fprintln(os.Stderr, "files-query-lint: violations found")
		os.Exit(1)
	}
}


