package main

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func TestLint_DetectsMissingFilter(t *testing.T) {
	src := `LIST_DOCUMENTS = """SELECT id FROM files.documents WHERE corpus_id = $1"""`
	errs := lint(src)
	if len(errs) == 0 {
		t.Fatalf("expected lint error for missing deleted_at filter; got none")
	}
}

func TestLint_PassesWhenFilterPresent(t *testing.T) {
	src := `LIST_DOCUMENTS = """SELECT id FROM files.documents WHERE corpus_id = $1 AND deleted_at IS NULL"""`
	if errs := lint(src); len(errs) != 0 {
		t.Errorf("expected zero errors, got %v", errs)
	}
}

func TestLint_IgnoresTrashAwareQueriesByName(t *testing.T) {
	// Queries explicitly named with "TRASH" or "SWEEPER" or "PURGE" are
	// trash-aware by design.
	for _, name := range []string{"LIST_TRASH_BY_CORPUS", "SELECT_TRASH_SWEEPER_CANDIDATES"} {
		src := name + ` = """SELECT id FROM files.documents WHERE corpus_id = $1 AND deleted_at IS NOT NULL"""`
		if errs := lint(src); len(errs) != 0 {
			t.Errorf("expected zero errors for %s, got %v", name, errs)
		}
	}
}

func TestLint_IgnoresQueriesWithExplicitDeletedAtIsNotNull(t *testing.T) {
	src := `LOCK_DOCUMENT_FOR_SWEEP = """SELECT id FROM files.documents WHERE id = $1 AND deleted_at IS NOT NULL FOR UPDATE"""`
	if errs := lint(src); len(errs) != 0 {
		t.Errorf("expected zero errors for explicit NOT NULL filter, got %v", errs)
	}
}

func TestLint_IgnoresStateAgnosticCleanupQueries(t *testing.T) {
	// LOCK_DOCUMENT_FOR_CLEANUP and LOCK_DOCUMENT_FOR_PURGE are
	// state-agnostic by design — caller has already validated state.
	for _, name := range []string{"LOCK_DOCUMENT_FOR_CLEANUP", "LOCK_DOCUMENT_FOR_PURGE"} {
		src := name + ` = """SELECT id FROM files.documents WHERE id = $1 FOR UPDATE"""`
		if errs := lint(src); len(errs) != 0 {
			t.Errorf("expected zero errors for %s, got %v", name, errs)
		}
	}
}

func TestLint_IgnoresWriteStatements(t *testing.T) {
	for _, w := range []string{
		`X = """DELETE FROM files.documents WHERE id = $1"""`,
		`Y = """UPDATE files.documents SET x = 1 WHERE id = $1"""`,
		`Z = """INSERT INTO files.documents (id) VALUES ($1)"""`,
	} {
		if errs := lint(w); len(errs) != 0 {
			t.Errorf("expected zero errors for write %q, got %v", w, errs)
		}
	}
}

func TestLint_FlagsMultilineSelect(t *testing.T) {
	src := `
LIST_DOCUMENTS_BY_CORPUS = """
    SELECT d.id::text
    FROM files.documents d
    WHERE d.corpus_id = $1::uuid
      AND d.id > $2::uuid
    ORDER BY d.id ASC
    LIMIT $3::int
"""
`
	errs := lint(src)
	if len(errs) == 0 {
		t.Fatalf("expected lint error for multi-line SELECT missing deleted_at filter")
	}
}

func TestLint_HonorsAllowTrashStateAgnosticMarker(t *testing.T) {
	// A query that is intentionally state-agnostic by design (caller
	// post-filters by deleted_at) can opt out via an inline allow marker
	// on the line(s) preceding the constant. This is the durable escape
	// hatch — intent is explicit at the query site, no naming
	// convention drift.
	src := `
# files-query-lint: allow-trash-state-agnostic
GET_DOCUMENT_BY_ID = """SELECT id FROM files.documents WHERE id = $1::uuid"""
`
	if errs := lint(src); len(errs) != 0 {
		t.Errorf("expected zero errors when allow marker is present, got %v", errs)
	}
}

func TestLint_DetectsMissingFilterInFStringConstant(t *testing.T) {
	// Query constants defined as Python f-strings (`= f"""..."""`) must be
	// scanned just like plain triple-quoted strings (`= """..."""`).
	src := `GET_CORPUS = f"""SELECT id FROM files.documents WHERE corpus_id = {placeholder}"""`
	errs := lint(src)
	if len(errs) == 0 {
		t.Fatalf("expected lint error for f-string SELECT missing deleted_at filter; got none")
	}
}

func TestLint_ScansLiveQueriesFileCleanly(t *testing.T) {
	// Smoke test: run lint against the actual queries.py and assert no
	// violations. This catches regressions if someone adds a new active-
	// doc SELECT without the filter.
	data, err := os.ReadFile("../../../services/files-svc/src/files_svc/db/queries.py")
	if err != nil {
		t.Skip("skipping live-file check: queries.py not found at expected path")
	}
	if errs := lint(string(data)); len(errs) != 0 {
		t.Errorf("queries.py has lint violations:\n%v", errs)
	}
}

// --- corpus-visibility rule ---

func TestCorpusVisibility_FlagsUngatedNamedQuery(t *testing.T) {
	// A brand-new query naming files.documents with no gate and no
	// allowlist entry must fail — this is the core acceptance criterion:
	// a future ungated query must fail the build instead of failing
	// silently.
	src := `LIST_DOCUMENTS_RAW = """SELECT id FROM files.documents WHERE corpus_id = $1::uuid"""`
	errs := lintCorpusVisibility(src)
	if len(errs) == 0 {
		t.Fatalf("expected a corpus-visibility violation for an ungated new query naming files.documents")
	}
}

func TestCorpusVisibility_FlagsUngatedFoldersAndIngestJobs(t *testing.T) {
	for _, src := range []string{
		`GET_FOLDER_RAW = """SELECT id FROM files.folders WHERE id = $1::uuid"""`,
		`GET_JOB_RAW = """SELECT id FROM files.ingest_jobs WHERE id = $1::uuid"""`,
	} {
		if errs := lintCorpusVisibility(src); len(errs) == 0 {
			t.Errorf("expected a corpus-visibility violation for %q", src)
		}
	}
}

